86	/// Prefill/decode GPU-sharing mode (`--decode-overlap`). Defined alongside the
87	/// stream plumbing in [`green_ctx`].
88	pub use green_ctx::DecodeOverlap;
89	
90	/// KV-offload (pegaflow) opt-in for the single-GPU Qwen3 path.
91	///
92	/// Disabled by default — the existing GPU-only prefix cache is unchanged.
93	/// When enabled, the executor saves sealed KV blocks to pegaflow's host tier
94	/// and prefetches CPU-resident prefixes back into HBM before prefill, so a
95	/// prompt that has fallen out of the GPU cache still skips recompute. Only the
96	/// single-GPU topology is supported (tensor parallel shards KV per rank).
97	#[derive(Clone, Debug, Eq, PartialEq)]
98	pub struct Qwen3OffloadOptions {
99	    enabled: bool,
100	    /// Host pinned-memory pool size (the CPU KV-tier capacity), in bytes.
101	    pinned_pool_bytes: usize,
102	    /// Back the pool with 2 MiB hugepages (the box must hold a reservation).
103	    use_hugepages: bool,
104	    /// `Some` joins the cross-instance P2P mesh: block hashes register with a
105	    /// MetaServer, peers pull missing prefixes over RDMA, and this engine
106	    /// serves theirs. The P/D disaggregation data plane.
107	    p2p: Option<Qwen3P2pOptions>,
108	    /// `Some` when the P/D prefill peer is vLLM (pegaflow connector): offload
109	    /// query keys switch from kvbm lineage hashes to vLLM's prefix-cache hash
110	    /// scheme so this decode node can find the blocks vLLM registered.
111	    vllm_compat: Option<Qwen3VllmCompatOptions>,
112	}
113	
114	/// Cross-instance P2P KV sharing (see `pegainfer_kv_offload::P2pConfig`).
115	#[derive(Clone, Debug, Eq, PartialEq)]
116	pub struct Qwen3P2pOptions {
117	    /// MetaServer gRPC address, e.g. `http://127.0.0.1:50056`.
118	    metaserver_addr: String,
119	    /// This engine's routable `IP:port` (literal socket address; also the
120	    /// P2P gRPC listen address, so hostnames are rejected at startup). Peers
121	    /// dial it for RDMA handshakes and block queries.
122	    advertise_addr: String,
123	    /// RDMA NIC device names (e.g. `mlx5_0`).
124	    rdma_nics: Vec<String>,
125	    /// Barrier a request's KV saves (host tier + MetaServer registration)
126	    /// before its `Finished` event is emitted. The prefill role in a P/D
127	    /// deployment turns this on so its HTTP response *is* the KV-ready signal;
128	    /// costs one write-pipeline + registration drain per finishing step, so
129	    /// leave it off on decode/serving instances.
130	    flush_on_finish: bool,
131	}
132	
133	/// Decode-node settings for a P/D deployment whose prefill node is vLLM with
134	/// the pegaflow connector. vLLM registers KV under its own prefix-cache block
135	/// hashes (`xxh3_128` over canonical-CBOR chained tuples — see
136	/// `pegainfer_kv_offload::VllmBlockHasher`); with this set, cold-request
137	/// offload queries derive those keys instead of kvbm lineage hashes, and a
138	/// zero hit waits out the producer's save/registration tail instead of
139	/// immediately prefilling from scratch.
140	///
141	/// Requires on every vLLM prefill process: `--prefix-caching-hash-algo
142	/// xxhash_cbor` and `PYTHONHASHSEED` set to `python_hash_seed` (unset, vLLM's
143	/// chain root is `os.urandom` — unreproducible across processes).
144	#[derive(Clone, Debug, Eq, PartialEq)]
145	pub struct Qwen3VllmCompatOptions {
146	    /// The `PYTHONHASHSEED` value shared with every vLLM prefill process.
147	    python_hash_seed: String,
148	    /// The P side's pegaflow-connector namespace: an 8-hex digest the
149	    /// connector derives from vLLM config and logs at startup
150	    /// (`namespace=...`). Both sides must address the same content domain.
151	    namespace: String,
152	    /// How long a cold request keeps re-querying a zero hit before giving up
153	    /// on the expected remote KV and prefilling locally. Covers the P side's
154	    /// post-response save + MetaServer-registration tail (tens of ms).
155	    miss_wait: std::time::Duration,
156	}
157	
158	impl Qwen3OffloadOptions {
159	    pub fn disabled() -> Self {
160	        Self {
161	            enabled: false,
162	            pinned_pool_bytes: 0,
163	            use_hugepages: false,
164	            p2p: None,
165	            vllm_compat: None,
166	        }
167	    }
168	
169	    pub fn enabled(pinned_pool_bytes: usize) -> Self {
170	        Self {
171	            enabled: true,
172	            pinned_pool_bytes,
173	            use_hugepages: false,
174	            p2p: None,
175	            vllm_compat: None,
176	        }
177	    }
178	
179	    #[must_use]
180	    fn with_p2p(mut self, p2p: Qwen3P2pOptions) -> Self {
181	        self.p2p = Some(p2p);
182	        self
183	    }
184	
185	    #[must_use]
186	    fn with_vllm_compat(mut self, compat: Qwen3VllmCompatOptions) -> Self {
187	        self.vllm_compat = Some(compat);
188	        self
189	    }
190	}
191	
192	impl Default for Qwen3OffloadOptions {
193	    fn default() -> Self {
194	        Self::disabled()
195	    }
196	}
