222	/// Server-facing launch knobs for the Qwen3 engine.
223	///
224	/// The binary maps raw CLI flags into this struct; [`launch`] then owns the
225	/// Qwen3 startup policy — the TP→device mapping and the LoRA↔CUDA-Graph
226	/// exclusion — and dispatches to the right low-level entry.
227	/// That policy lives with the model instead of leaking into the server.
228	#[derive(Clone, Debug)]
229	#[allow(
230	    clippy::struct_excessive_bools,
231	    reason = "these launch flags are independent server options, not states"
232	)]
233	pub struct Qwen3LaunchOptions {
234	    /// CUDA device for single-GPU loads (ignored when `tp_size > 1`).
235	    pub device_ordinal: usize,
236	    /// Tensor-parallel world size; `> 1` uses devices `0..tp_size`.
237	    pub tp_size: usize,
238	    /// Whether the user requested CUDA Graph. LoRA serving forces it off;
239	    /// under tensor parallelism every decode graph is pre-captured at startup.
240	    pub cuda_graph: bool,
241	    /// Export the live rank-0, batch-1 SplitKv decode graph during startup.
242	    /// The requested PNG gets a detailed sibling `.dot` for LLM inspection.
243	    pub dump_graph_png: Option<PathBuf>,
244	    pub offload: Qwen3OffloadOptions,
245	    pub no_prefix_cache: bool,
246	    pub max_prefill_tokens: usize,
247	    pub memory: Qwen3MemoryOptions,
248	    /// `Some` switches on LoRA serving (and disables CUDA Graph).
249	    pub lora: Option<Qwen3LoraOptions>,
250	    /// How prefill and decode share the GPU (`--decode-overlap`).
251	    pub decode_overlap: DecodeOverlap,
252	    pub batch_invariant: bool,
253	    /// `Some` enables DFlash speculative decoding with this drafter model.
254	    /// Single-GPU only and mutually exclusive with LoRA and KV offload.
255	    pub dflash_draft_model_path: Option<PathBuf>,
256	}
257	
258	/// Start the Qwen3 engine from server-facing [`Qwen3LaunchOptions`].
259	#[allow(
260	    clippy::needless_pass_by_value,
261	    reason = "launch is a one-shot ownership boundary used by external worker threads"
262	)]
263	pub fn launch(model_path: &Path, options: Qwen3LaunchOptions) -> Result<Engine> {
264	    let device_ordinals = if options.tp_size == 1 {
265	        vec![options.device_ordinal]
266	    } else {
267	        (0..options.tp_size).collect()
268	    };
269	    // LoRA serving repoints adapter weights between steps, which a captured
270	    // decode graph bakes in.
271	    let enable_cuda_graph = if options.lora.is_some() {
272	        if options.cuda_graph {
273	            warn!("Qwen3: CUDA Graph is disabled while LoRA serving is enabled");
274	        }
275	        false
276	    } else {
277	        options.cuda_graph
278	    };
279	    if let Some(path) = &options.dump_graph_png {
280	        anyhow::ensure!(
281	            enable_cuda_graph,
282	            "Qwen3 graph export requires CUDA Graph enabled"
283	        );
284	        anyhow::ensure!(
285	            options.lora.is_none(),
286	            "Qwen3 graph export is not supported with LoRA serving"
287	        );
288	        pegainfer_core::cuda_graph::validate_graph_dump_request(path)?;
289	    }
290	    let engine = EngineLoadOptions {
291	        enable_cuda_graph,
292	        device_ordinals,
293	        parallel_config: None,
294	        ep_backend: EpBackend::Nccl,
295	        seed: 42,
296	    };
297	    if options.offload.enabled {
298	        info!(
299	            "Qwen3 KV offload enabled: host tier {:.1} GiB, no_prefix_cache={}",
300	            options.offload.pinned_pool_bytes as f64 / f64::from(1u32 << 30),
301	            options.no_prefix_cache
302	        );
303	    }
304	    // Also rejected at enable_decode_overlap (the load-bearing guard); failing
305	    // here saves the full TP model load + graph pre-capture before the error.
306	    anyhow::ensure!(
307	        options.tp_size == 1 || matches!(options.decode_overlap, DecodeOverlap::Off),
308	        "decode-overlap is unsupported under tensor parallelism"
309	    );
310	    anyhow::ensure!(
311	        !(options.dflash_draft_model_path.is_some() && options.lora.is_some()),
312	        "DFlash speculative decoding cannot be combined with LoRA serving"
313	    );
314	    anyhow::ensure!(
315	        options.dflash_draft_model_path.is_none()
316	            || matches!(options.decode_overlap, DecodeOverlap::Off),
317	        "DFlash speculative decoding cannot be combined with decode overlap \
318	         (--decode-overlap): the speculative path never takes the unified overlap \
319	         route, so the overlap streams would only waste VRAM the drafter needs"
320	    );
321	    match options.lora {
322	        Some(lora) => {
323	            info!(
324	                "Starting Qwen3 engine with LoRA control; max_loras={}, max_lora_rank={}",
325	                lora.max_loras, lora.max_lora_rank
326	            );
327	            start_engine_with_lora_control(
328	                model_path,
329	                engine,
330	                lora,
331	                options.offload,
332	                options.no_prefix_cache,
333	                options.max_prefill_tokens,
334	                options.memory,
335	                options.decode_overlap,
336	                options.batch_invariant,
337	            )
338	        }
339	        None => start_engine_with_offload_inner(
340	            model_path,
341	            engine,
342	            options.offload,
343	            options.no_prefix_cache,
344	            options.max_prefill_tokens,
345	            options.memory,
346	            options.decode_overlap,
347	            options.batch_invariant,
348	            options.dflash_draft_model_path.as_deref(),
349	            options.dump_graph_png.as_deref(),
350	        ),
351	    }
352	}
353	
354	pub fn start_engine(model_path: &Path, options: EngineLoadOptions) -> Result<Engine> {
355	    start_engine_with_offload(
356	        model_path,
357	        options,
358	        Qwen3OffloadOptions::disabled(),
359	        false,
360	        DEFAULT_MAX_PREFILL_TOKENS,
361	        Qwen3MemoryOptions::default(),
362	        DecodeOverlap::Off,
363	        false,
364	        None,
365	    )
366	}
367	
368	/// Like [`start_engine`] but with pegaflow KV offload (single-GPU only). The
369	/// host tier persists sealed KV blocks and serves CPU-resident prefixes back
370	/// into HBM before prefill.
371	///
372	/// `no_prefix_cache` is the vLLM-style switch (see
373	/// [`Qwen3Executor::set_no_prefix_cache`](runtime::Qwen3Executor::set_no_prefix_cache)):
374	/// without offload it disables prefix matching outright; with offload it keeps
375	/// the host tier but stops cross-request HBM reuse, so every prefix is served
376	/// from L2 — the pure-L2 benchmark mode.
377	///
378	/// `max_prefill_tokens` caps the total prompt tokens batch-prefilled in one
379	/// scheduler step (see [`DEFAULT_MAX_PREFILL_TOKENS`]).
380	#[allow(clippy::too_many_arguments)]
381	pub fn start_engine_with_offload(
382	    model_path: &Path,
383	    options: EngineLoadOptions,
384	    offload_options: Qwen3OffloadOptions,
385	    no_prefix_cache: bool,
386	    max_prefill_tokens: usize,
387	    memory_options: Qwen3MemoryOptions,
388	    decode_overlap: DecodeOverlap,
389	    batch_invariant: bool,
390	    dflash_draft_model_path: Option<&Path>,
391	) -> Result<Engine> {
392	    start_engine_with_offload_inner(
393	        model_path,
394	        options,
395	        offload_options,
396	        no_prefix_cache,
397	        max_prefill_tokens,
398	        memory_options,
399	        decode_overlap,
400	        batch_invariant,
401	        dflash_draft_model_path,
402	        None,
403	    )
404	}
405	
406	#[allow(clippy::too_many_arguments)]
407	fn start_engine_with_offload_inner(
408	    model_path: &Path,
409	    options: EngineLoadOptions,
410	    offload_options: Qwen3OffloadOptions,
411	    no_prefix_cache: bool,
412	    max_prefill_tokens: usize,
413	    memory_options: Qwen3MemoryOptions,
414	    decode_overlap: DecodeOverlap,
415	    batch_invariant: bool,
416	    dflash_draft_model_path: Option<&Path>,
417	    dump_graph_png: Option<&Path>,
418	) -> Result<Engine> {
419	    crate::spec_env::validate()?;
420	    let EngineLoadOptions {
421	        enable_cuda_graph,
422	        device_ordinals,
423	        seed,
424	        ..
425	    } = options;
426	    let model_path = model_path
427	        .to_str()
428	        .ok_or_else(|| anyhow::anyhow!("model path must be valid UTF-8"))?;
429	    if batch_invariant {
430	        ensure_batch_invariant_supported(
431	            decode_overlap,
432	            no_prefix_cache,
433	            offload_options.enabled,
434	            dflash_draft_model_path.is_some(),
435	            device_ordinals.len(),
436	        )?;
437	    }
438	    apply_batch_invariant_policy(batch_invariant);
439	    let dflash_draft_model_path = dflash_draft_model_path
440	        .map(|path| {
441	            path.to_str()
442	                .ok_or_else(|| anyhow::anyhow!("DFlash draft model path must be valid UTF-8"))
443	        })
444	        .transpose()?;
445	    frontend_adapter::start_qwen3(
446	        model_path,
447	        enable_cuda_graph,
448	        &device_ordinals,
449	        seed,
450	        offload_options,
451	        no_prefix_cache,
452	        max_prefill_tokens,
453	        memory_options,
454	        decode_overlap,
455	        dflash_draft_model_path,
456	        dump_graph_png,
457	    )
458	}
459	
460	pub fn start_engine_with_lora_control(
461	    model_path: &Path,
462	    options: EngineLoadOptions,
463	    lora_options: Qwen3LoraOptions,
464	    offload_options: Qwen3OffloadOptions,
465	    no_prefix_cache: bool,
466	    max_prefill_tokens: usize,
467	    memory_options: Qwen3MemoryOptions,
468	    decode_overlap: DecodeOverlap,
469	    batch_invariant: bool,
470	) -> Result<Engine> {
471	    crate::spec_env::validate()?;
472	    let EngineLoadOptions {
473	        enable_cuda_graph,
474	        device_ordinals,
475	        seed,
476	        ..
477	    } = options;
478	    let model_path = model_path
479	        .to_str()
480	        .ok_or_else(|| anyhow::anyhow!("model path must be valid UTF-8"))?;
481	    if batch_invariant {
482	        anyhow::bail!(
483	            "--batch-invariant is not supported with LoRA: the decode-GEMM pin warms and self-checks \
484	             only the base projections, not the per-adapter rank-K shapes, so the combination is \
485	             unverified"
486	        );
487	    }
488	    anyhow::ensure!(
489	        matches!(decode_overlap, DecodeOverlap::Off),
490	        "LoRA serving does not support --decode-overlap"
491	    );
492	    apply_batch_invariant_policy(batch_invariant);
493	    frontend_adapter::start_qwen3_with_lora_control(
494	        model_path,
495	        enable_cuda_graph,
496	        &device_ordinals,
497	        seed,
498	        lora_options.validate()?,
499	        offload_options,
500	        no_prefix_cache,
501	        max_prefill_tokens,
502	        memory_options,
503	    )
504	}
505	
506	fn apply_batch_invariant_policy(batch_invariant: bool) {
507	    use pegainfer_kernels::ops::NumericPolicy;
508	    use pegainfer_kernels::ops::set_numeric_policy;
509	    let policy = if batch_invariant {
510	        NumericPolicy::Pin
511	    } else {
512	        NumericPolicy::Tuned
513	    };
514	    info!("Qwen3 numeric policy: {policy:?} (--batch-invariant={batch_invariant})");
515	    set_numeric_policy(policy);
516	}
517	
518	fn ensure_batch_invariant_supported(
519	    decode_overlap: DecodeOverlap,
520	    no_prefix_cache: bool,
521	    offload: bool,
522	    dflash: bool,
523	    world_size: usize,
524	) -> Result<()> {
525	    if !matches!(decode_overlap, DecodeOverlap::Off) {
526	        anyhow::bail!(
527	            "--batch-invariant is not compatible with --decode-overlap; the stream override would force the pinned GEMM to bail at runtime"
528	        );
529	    }
530	    if offload {
531	        anyhow::bail!(
532	            "--batch-invariant is not supported with KV offload: offload keeps prefix matching on \
533	             (--no-prefix-cache only disables HBM retention there), and a host-tier prefix hit \
534	             shifts a prompt's chunk boundaries off the request-local grid"
535	        );
536	    }
537	    if world_size > 1 {
538	        anyhow::bail!(
539	            "--batch-invariant is not supported with tensor parallelism: world_size={world_size} has unverified cross-rank reduction order"
540	        );
541	    }
542	    if dflash {
543	        anyhow::bail!(
544	            "--batch-invariant is not supported with DFlash speculative decoding: the decode-GEMM \
545	             pin warms and self-checks only the base projections, so the drafter's fc/MLP GEMMs \
546	             are not pinned and would bail at the GEMM boundary under Pin"
547	        );
548	    }
549	    if !no_prefix_cache {
550	        anyhow::bail!(
551	            "--batch-invariant requires --no-prefix-cache; prefix-cache hits move a prompt's chunk \
552	             boundaries off the request-local grid, so batch-invariant prefill cannot be provided"
553	        );
554	    }
555	    Ok(())
556	}
