222	/// Server-facing launch knobs for the Qwen3 engine.
223	///
224	/// The binary maps raw CLI flags into this struct; [`launch`] then owns the
225	/// Qwen3 startup policy — the TP→device mapping and the LoRA↔CUDA-Graph
226	/// exclusion — and dispatches to the right low-level entry.
227	/// That policy lives with the model instead of leaking into the server.
228	#[derive(Clone, Debug)]
229	#[allow(
230	    clippy::struct_excessive_bools,
231	    reason = "these launch flags are independent server options, not states"
232	)]
233	pub struct Qwen3LaunchOptions {
234	    /// CUDA device for single-GPU loads (ignored when `tp_size > 1`).
235	    pub device_ordinal: usize,
236	    /// Tensor-parallel world size; `> 1` uses devices `0..tp_size`.
237	    pub tp_size: usize,
238	    /// Whether the user requested CUDA Graph. LoRA serving forces it off;
239	    /// under tensor parallelism every decode graph is pre-captured at startup.
240	    pub cuda_graph: bool,
241	    /// Export the live rank-0, batch-1 SplitKv decode graph during startup.
242	    /// The requested PNG gets a detailed sibling `.dot` for LLM inspection.
243	    pub dump_graph_png: Option<PathBuf>,
244	    pub offload: Qwen3OffloadOptions,
245	    pub no_prefix_cache: bool,
246	    pub max_prefill_tokens: usize,
247	    pub memory: Qwen3MemoryOptions,
248	    /// `Some` switches on LoRA serving (and disables CUDA Graph).
249	    pub lora: Option<Qwen3LoraOptions>,
250	    /// How prefill and decode share the GPU (`--decode-overlap`).
251	    pub decode_overlap: DecodeOverlap,
252	    pub batch_invariant: bool,
253	    /// `Some` enables DFlash speculative decoding with this drafter model.
254	    /// Single-GPU only and mutually exclusive with LoRA and KV offload.
255	    pub dflash_draft_model_path: Option<PathBuf>,
256	}
257	
258	/// Start the Qwen3 engine from server-facing [`Qwen3LaunchOptions`].
259	#[allow(
260	    clippy::needless_pass_by_value,
261	    reason = "launch is a one-shot ownership boundary used by external worker threads"
262	)]
263	pub fn launch(model_path: &Path, options: Qwen3LaunchOptions) -> Result<Engine> {
264	    let device_ordinals = if options.tp_size == 1 {
265	        vec![options.device_ordinal]
266	    } else {
267	        (0..options.tp_size).collect()
268	    };
269	    // LoRA serving repoints adapter weights between steps, which a captured
270	    // decode graph bakes in.
271	    let enable_cuda_graph = if options.lora.is_some() {
272	        if options.cuda_graph {
273	            warn!("Qwen3: CUDA Graph is disabled while LoRA serving is enabled");
274	        }
275	        false
276	    } else {
277	        options.cuda_graph
278	    };
279	    if let Some(path) = &options.dump_graph_png {
280	        anyhow::ensure!(
281	            enable_cuda_graph,
282	            "Qwen3 graph export requires CUDA Graph enabled"
283	        );
284	        anyhow::ensure!(
285	            options.lora.is_none(),
286	            "Qwen3 graph export is not supported with LoRA serving"
287	        );
288	        pegainfer_core::cuda_graph::validate_graph_dump_request(path)?;
289	    }
290	    let engine = EngineLoadOptions {
291	        enable_cuda_graph,
292	        device_ordinals,
293	        parallel_config: None,
294	        ep_backend: EpBackend::Nccl,
295	        seed: 42,
296	    };
297	    if options.offload.enabled {
298	        info!(
299	            "Qwen3 KV offload enabled: host tier {:.1} GiB, no_prefix_cache={}",
300	            options.offload.pinned_pool_bytes as f64 / f64::from(1u32 << 30),
301	            options.no_prefix_cache
302	        );
303	    }
304	    // Also rejected at enable_decode_overlap (the load-bearing guard); failing
305	    // here saves the full TP model load + graph pre-capture before the error.
306	    anyhow::ensure!(
307	        options.tp_size == 1 || matches!(options.decode_overlap, DecodeOverlap::Off),
308	        "decode-overlap is unsupported under tensor parallelism"
309	    );
310	    anyhow::ensure!(
311	        !(options.dflash_draft_model_path.is_some() && options.lora.is_some()),
312	        "DFlash speculative decoding cannot be combined with LoRA serving"
313	    );
314	    anyhow::ensure!(
315	        options.dflash_draft_model_path.is_none()
316	            || matches!(options.decode_overlap, DecodeOverlap::Off),
317	        "DFlash speculative decoding cannot be combined with decode overlap \
318	         (--decode-overlap): the speculative path never takes the unified overlap \
319	         route, so the overlap streams would only waste VRAM the drafter needs"
320	    );
321	    match options.lora {
322	        Some(lora) => {
323	            info!(
324	                "Starting Qwen3 engine with LoRA control; max_loras={}, max_lora_rank={}",
325	                lora.max_loras, lora.max_lora_rank
326	            );
327	            start_engine_with_lora_control(
328	                model_path,
329	                engine,
330	                lora,
331	                options.offload,
332	                options.no_prefix_cache,
333	                options.max_prefill_tokens,
334	                options.memory,
335	                options.decode_overlap,
336	                options.batch_invariant,
337	            )
338	        }
339	        None => start_engine_with_offload_inner(
340	            model_path,
341	            engine,
342	            options.offload,
343	            options.no_prefix_cache,
344	            options.max_prefill_tokens,
345	            options.memory,
346	            options.decode_overlap,
347	            options.batch_invariant,
348	            options.dflash_draft_model_path.as_deref(),
349	            options.dump_graph_png.as_deref(),
350	        ),
351	    }
352	}
