391	) -> Result<Engine> {
392	    start_engine_with_offload_inner(
393	        model_path,
394	        options,
395	        offload_options,
396	        no_prefix_cache,
397	        max_prefill_tokens,
398	        memory_options,
399	        decode_overlap,
400	        batch_invariant,
401	        dflash_draft_model_path,
402	        None,
403	    )
404	}
