406	#[allow(clippy::too_many_arguments)]
407	fn start_engine_with_offload_inner(
408	    model_path: &Path,
409	    options: EngineLoadOptions,
410	    offload_options: Qwen3OffloadOptions,
411	    no_prefix_cache: bool,
412	    max_prefill_tokens: usize,
413	    memory_options: Qwen3MemoryOptions,
414	    decode_overlap: DecodeOverlap,
415	    batch_invariant: bool,
416	    dflash_draft_model_path: Option<&Path>,
417	    dump_graph_png: Option<&Path>,
418	) -> Result<Engine> {
419	    crate::spec_env::validate()?;
420	    let EngineLoadOptions {
421	        enable_cuda_graph,
422	        device_ordinals,
423	        seed,
424	        ..
425	    } = options;
426	    let model_path = model_path
427	        .to_str()
428	        .ok_or_else(|| anyhow::anyhow!("model path must be valid UTF-8"))?;
429	    if batch_invariant {
430	        ensure_batch_invariant_supported(
431	            decode_overlap,
432	            no_prefix_cache,
433	            offload_options.enabled,
434	            dflash_draft_model_path.is_some(),
435	            device_ordinals.len(),
436	        )?;
437	    }
438	    apply_batch_invariant_policy(batch_invariant);
439	    let dflash_draft_model_path = dflash_draft_model_path
440	        .map(|path| {
441	            path.to_str()
442	                .ok_or_else(|| anyhow::anyhow!("DFlash draft model path must be valid UTF-8"))
443	        })
444	        .transpose()?;
445	    frontend_adapter::start_qwen3(
446	        model_path,
447	        enable_cuda_graph,
448	        &device_ordinals,
449	        seed,
450	        offload_options,
451	        no_prefix_cache,
452	        max_prefill_tokens,
453	        memory_options,
454	        decode_overlap,
455	        dflash_draft_model_path,
456	        dump_graph_png,
457	    )
458	}
