460	pub fn start_engine_with_lora_control(
461	    model_path: &Path,
462	    options: EngineLoadOptions,
463	    lora_options: Qwen3LoraOptions,
464	    offload_options: Qwen3OffloadOptions,
465	    no_prefix_cache: bool,
466	    max_prefill_tokens: usize,
467	    memory_options: Qwen3MemoryOptions,
468	    decode_overlap: DecodeOverlap,
469	    batch_invariant: bool,
470	) -> Result<Engine> {
471	    crate::spec_env::validate()?;
472	    let EngineLoadOptions {
473	        enable_cuda_graph,
474	        device_ordinals,
475	        seed,
476	        ..
477	    } = options;
478	    let model_path = model_path
479	        .to_str()
480	        .ok_or_else(|| anyhow::anyhow!("model path must be valid UTF-8"))?;
481	    if batch_invariant {
482	        anyhow::bail!(
483	            "--batch-invariant is not supported with LoRA: the decode-GEMM pin warms and self-checks \
484	             only the base projections, not the per-adapter rank-K shapes, so the combination is \
485	             unverified"
486	        );
487	    }
488	    anyhow::ensure!(
489	        matches!(decode_overlap, DecodeOverlap::Off),
490	        "LoRA serving does not support --decode-overlap"
491	    );
492	    apply_batch_invariant_policy(batch_invariant);
493	    frontend_adapter::start_qwen3_with_lora_control(
494	        model_path,
495	        enable_cuda_graph,
496	        &device_ordinals,
497	        seed,
498	        lora_options.validate()?,
499	        offload_options,
500	        no_prefix_cache,
501	        max_prefill_tokens,
502	        memory_options,
503	    )
504	}
505	
506	fn apply_batch_invariant_policy(batch_invariant: bool) {
507	    use pegainfer_kernels::ops::NumericPolicy;
508	    use pegainfer_kernels::ops::set_numeric_policy;
509	    let policy = if batch_invariant {
510	        NumericPolicy::Pin
511	    } else {
512	        NumericPolicy::Tuned
513	    };
514	    info!("Qwen3 numeric policy: {policy:?} (--batch-invariant={batch_invariant})");
515	    set_numeric_policy(policy);
516	}
517	
518	fn ensure_batch_invariant_supported(
519	    decode_overlap: DecodeOverlap,
520	    no_prefix_cache: bool,
521	    offload: bool,
522	    dflash: bool,
523	    world_size: usize,
524	) -> Result<()> {
525	    if !matches!(decode_overlap, DecodeOverlap::Off) {
526	        anyhow::bail!(
527	            "--batch-invariant is not compatible with --decode-overlap; the stream override would force the pinned GEMM to bail at runtime"
528	        );
529	    }
530	    if offload {
531	        anyhow::bail!(
532	            "--batch-invariant is not supported with KV offload: offload keeps prefix matching on \
533	             (--no-prefix-cache only disables HBM retention there), and a host-tier prefix hit \
534	             shifts a prompt's chunk boundaries off the request-local grid"
535	        );
536	    }
537	    if world_size > 1 {
538	        anyhow::bail!(
539	            "--batch-invariant is not supported with tensor parallelism: world_size={world_size} has unverified cross-rank reduction order"
540	        );
541	    }
542	    if dflash {
543	        anyhow::bail!(
544	            "--batch-invariant is not supported with DFlash speculative decoding: the decode-GEMM \
545	             pin warms and self-checks only the base projections, so the drafter's fc/MLP GEMMs \
546	             are not pinned and would bail at the GEMM boundary under Pin"
547	        );
548	    }
549	    if !no_prefix_cache {
550	        anyhow::bail!(
551	            "--batch-invariant requires --no-prefix-cache; prefix-cache hits move a prompt's chunk \
552	             boundaries off the request-local grid, so batch-invariant prefill cannot be provided"
553	        );
554	    }
555	    Ok(())
556	}
