124	impl ModelLine for Qwen3Line {
125	    fn name(&self) -> &'static str {
126	        "Qwen3"
127	    }
128	
129	    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
130	        let model_type = config.get("model_type").and_then(serde_json::Value::as_str);
131	        if model_type != Some("qwen3") {
132	            return Err(format!("model_type {model_type:?} is not \"qwen3\""));
133	        }
134	        crate::probe_config_json(config).map_err(|error| error.to_string())
135	    }
136	
137	    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
138	        Qwen3Cli::augment_args(cmd)
139	    }
140	
141	    fn consumed_shared_args(&self) -> &'static [&'static str] {
142	        &[
143	            "cuda_graph",
144	            "dump_graph_png",
145	            "device_ordinal",
146	            "tp_size",
147	            "kv_offload",
148	            "kv_offload_host_gib",
149	            "kv_offload_hugepages",
150	            "kv_p2p_metaserver_addr",
151	            "kv_p2p_advertise_addr",
152	            "kv_p2p_nics",
153	            "no_prefix_cache",
154	            "max_prefill_tokens",
155	            "dflash_draft_model_path",
156	            "decode_overlap",
157	            "decode_sm_pct",
158	        ]
159	    }
160	
161	    fn arg_requirements(&self) -> &'static [ArgRequirement] {
162	        &[
163	            ("kv_p2p_flush_on_finish", &["kv_p2p_metaserver_addr"]),
164	            (
165	                "kv_pd_vllm_seed",
166	                &["kv_p2p_metaserver_addr", "kv_pd_vllm_namespace"],
167	            ),
168	            ("kv_pd_vllm_namespace", &["kv_pd_vllm_seed"]),
169	            ("kv_pd_miss_wait_ms", &["kv_pd_vllm_seed"]),
170	        ]
171	    }
172	
173	    fn validate(
174	        &self,
175	        ctx: &LaunchContext<'_>,
176	        provided: &BTreeSet<String>,
177	    ) -> Result<(), CliError> {
178	        let cli = cli(ctx);
179	        let shared = ctx.shared;
180	        if !cli.enable_lora && !cli.lora_modules.is_empty() {
181	            return Err(CliError::rule("--lora-modules requires --enable-lora"));
182	        }
183	        if !cli.enable_lora
184	            && (provided.contains("max_loras") || provided.contains("max_lora_rank"))
185	        {
186	            return Err(CliError::rule(
187	                "--max-loras and --max-lora-rank require --enable-lora",
188	            ));
189	        }
190	        if shared.dump_graph_png.is_some() && cli.enable_lora {
191	            return Err(CliError::rule(
192	                "--dump-graph-png is not supported with --enable-lora (LoRA disables CUDA Graph)",
193	            ));
194	        }
195	        if shared.decode_overlap != CliDecodeOverlap::Off && shared.tp_size > 1 {
196	            return Err(CliError::rule(
197	                "--decode-overlap is single-GPU only; tp_size>1 has no prefill/decode overlap",
198	            ));
199	        }
200	        if cli.batch_invariant {
201	            if cli.enable_lora {
202	                return Err(CliError::rule(
203	                    "--batch-invariant is not supported with --enable-lora; enable one at a time",
204	                ));
205	            }
206	            if shared.decode_overlap != CliDecodeOverlap::Off {
207	                return Err(CliError::rule(
208	                    "--batch-invariant is not compatible with --decode-overlap; the stream override would force the pinned GEMM to bail at runtime",
209	                ));
210	            }
211	            if shared.kv_offload {
212	                return Err(CliError::rule(
213	                    "--batch-invariant is not supported with --kv-offload: offload keeps prefix matching \
214	                     on (--no-prefix-cache only disables HBM retention there), and a host-tier prefix hit \
215	                     shifts a prompt's chunk boundaries off the request-local grid",
216	                ));
217	            }
218	            if shared.dflash_draft_model_path.is_some() {
219	                return Err(CliError::rule(
220	                    "--batch-invariant is not supported with DFlash speculative decoding; enable one at a time",
221	                ));
222	            }
223	            if shared.tp_size > 1 {
224	                return Err(CliError::rule(
225	                    "--batch-invariant is not supported with --tp-size > 1; enable one at a time",
226	                ));
227	            }
228	            if !shared.no_prefix_cache {
229	                return Err(CliError::rule(
230	                    "--batch-invariant requires --no-prefix-cache; prefix-cache hits move a prompt's chunk \
231	                     boundaries off the request-local grid, so batch-invariant prefill cannot be provided",
232	                ));
233	            }
234	        }
235	        if shared.dflash_draft_model_path.is_some() {
236	            if cli.enable_lora {
237	                return Err(CliError::rule(
238	                    "--dflash-draft-model-path is not supported with --enable-lora",
239	                ));
240	            }
241	            if shared.kv_offload {
242	                return Err(CliError::rule(
243	                    "--dflash-draft-model-path is not supported with --kv-offload",
244	                ));
245	            }
246	            if shared.tp_size != 1 {
247	                return Err(CliError::rule(
248	                    "--dflash-draft-model-path currently requires --tp-size=1",
249	                ));
250	            }
251	        }
252	        Ok(())
253	    }
254	
255	    fn serve_plan(&self, ctx: &LaunchContext<'_>) -> Result<ServePlan, CliError> {
256	        let cli = cli(ctx);
257	        Ok(ServePlan {
258	            lora_modules: cli.enable_lora.then(|| cli.lora_modules.clone()),
259	            ..ServePlan::default()
260	        })
261	    }
262	
263	    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine> {
264	        let cli = cli(ctx);
265	        let shared = ctx.shared;
266	        let offload = if shared.kv_offload {
267	            let bytes = (shared.kv_offload_host_gib * f64::from(1u32 << 30)) as usize;
268	            let mut offload = Qwen3OffloadOptions::enabled(bytes);
269	            offload.use_hugepages = shared.kv_offload_hugepages;
270	            if let (Some(metaserver_addr), Some(advertise_addr)) = (
271	                shared.kv_p2p_metaserver_addr.clone(),
272	                shared.kv_p2p_advertise_addr.clone(),
273	            ) {
274	                offload = offload.with_p2p(Qwen3P2pOptions {
275	                    metaserver_addr,
276	                    advertise_addr,
277	                    rdma_nics: shared.kv_p2p_nics.clone(),
278	                    flush_on_finish: cli.kv_p2p_flush_on_finish,
279	                });
280	            }
281	            if let Some(seed) = cli.kv_pd_vllm_seed.clone() {
282	                offload = offload.with_vllm_compat(Qwen3VllmCompatOptions {
283	                    python_hash_seed: seed,
284	                    namespace: cli
285	                        .kv_pd_vllm_namespace
286	                        .clone()
287	                        .expect("clap requires kv_pd_vllm_namespace"),
288	                    miss_wait: std::time::Duration::from_millis(cli.kv_pd_miss_wait_ms),
289	                });
290	            }
291	            offload
292	        } else {
293	            Qwen3OffloadOptions::disabled()
294	        };
295	        let lora = cli.enable_lora.then_some(Qwen3LoraOptions {
296	            max_loras: cli.max_loras,
297	            max_lora_rank: cli.max_lora_rank,
298	        });
299	        let kv_cache_memory_margin_bytes = cli
300	            .kv_cache_memory_margin_mib
301	            .checked_mul(1 << 20)
302	            .ok_or_else(|| {
303	                anyhow::anyhow!(
304	                    "--kv-cache-memory-margin-mib is too large: {}",
305	                    cli.kv_cache_memory_margin_mib
306	                )
307	            })?;
308	        crate::launch(
309	            ctx.model_path,
310	            Qwen3LaunchOptions {
311	                device_ordinal: shared.device_ordinal,
312	                tp_size: shared.tp_size,
313	                cuda_graph: shared.cuda_graph,
314	                dump_graph_png: shared.dump_graph_png.clone(),
315	                offload,
316	                no_prefix_cache: shared.no_prefix_cache,
317	                max_prefill_tokens: shared
318	                    .max_prefill_tokens
319	                    .unwrap_or(crate::DEFAULT_MAX_PREFILL_TOKENS),
320	                memory: Qwen3MemoryOptions::new(
321	                    cli.gpu_memory_utilization,
322	                    kv_cache_memory_margin_bytes,
323	                    cli.kv_page_size,
324	                )
325	                .validate()?,
326	                lora,
327	                decode_overlap: resolve_decode_overlap(shared.decode_overlap, shared.decode_sm_pct),
328	                batch_invariant: cli.batch_invariant,
329	                dflash_draft_model_path: shared.dflash_draft_model_path.clone(),
330	            },
331	        )
332	        .map(LaunchedEngine::Stepped)
333	    }
334	}
335	
336	fn parse_max_lora_rank_arg(value: &str) -> Result<usize, String> {
337	    let rank = value
338	        .parse::<usize>()
339	        .map_err(|error| format!("invalid --max-lora-rank: {error}"))?;
340	    if Qwen3LoraOptions::is_supported_max_lora_rank(rank) {
341	        Ok(rank)
342	    } else {
343	        Err(format!(
344	            "--max-lora-rank must be one of: {}",
345	            Qwen3LoraOptions::supported_max_lora_ranks_display()
346	        ))
347	    }
348	}
349	
350	/// PYTHONHASHSEED as vLLM accepts it: a decimal integer in [0, 4294967295].
351	/// An empty or malformed seed would derive a well-formed key space that can
352	/// never match the peer — a config error must fail here, not as slow requests.
353	fn parse_pythonhashseed(s: &str) -> Result<String, String> {
354	    if s.parse::<u32>().is_err() || s.starts_with('+') {
355	        return Err(format!(
356	            "PYTHONHASHSEED must be a decimal integer in [0, 4294967295], got {s:?}"
357	        ));
358	    }
359	    Ok(s.to_string())
360	}
361	
362	/// A pegaflow namespace digest: exactly 8 lowercase hex chars.
363	fn parse_pegaflow_namespace(s: &str) -> Result<String, String> {
364	    if s.len() != 8
365	        || !s
366	            .bytes()
367	            .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
368	    {
369	        return Err(format!(
370	            "namespace must be an 8-char lowercase hex digest, got {s:?}"
371	        ));
372	    }
373	    Ok(s.to_string())
374	}
