141	    fn consumed_shared_args(&self) -> &'static [&'static str] {
142	        &[
143	            "cuda_graph",
144	            "dump_graph_png",
145	            "device_ordinal",
146	            "tp_size",
147	            "kv_offload",
148	            "kv_offload_host_gib",
149	            "kv_offload_hugepages",
150	            "kv_p2p_metaserver_addr",
151	            "kv_p2p_advertise_addr",
152	            "kv_p2p_nics",
153	            "no_prefix_cache",
154	            "max_prefill_tokens",
155	            "dflash_draft_model_path",
156	            "decode_overlap",
157	            "decode_sm_pct",
158	        ]
159	    }
