28	
29	/// An in-flight request being decoded.
30	pub(crate) struct ActiveRequestState {
31	    pub(crate) request_id: RequestId,
32	    pub(crate) lora_adapter: Option<String>,
33	    pub(crate) last_token: u32,
34	    pub(crate) generated_count: usize,
35	    pub(crate) max_tokens: usize,
36	    pub(crate) prompt_len: usize,
37	    pub(crate) params: SamplingParams,
38	    pub(crate) stop_policy: StopPolicy,
39	    /// Completion top-k count; None disables scoring, Some(0) scores only the chosen token.
40	    pub(crate) logprobs: Option<usize>,
41	}
42	
43	/// A request between submission and promotion, `Clone` because the decode-overlap
44	/// path keeps a copy for async-prefill poll resolution. Its engine-contract
45	/// handle lives in the adapter's registry, keyed by `request_id` — never here.
46	#[derive(Clone)]
47	pub(crate) struct PendingRequest {
48	    pub(crate) request_id: RequestId,
49	    pub(crate) lora_adapter: Option<String>,
50	    pub(crate) prompt_tokens: Vec<u32>,
51	    pub(crate) params: SamplingParams,
52	    pub(crate) stop_policy: StopPolicy,
53	    pub(crate) max_tokens: usize,
54	    pub(crate) logprobs: Option<usize>,
55	    pub(crate) prompt_logprobs: Option<usize>,
56	    /// Whether this request has already been offered to async KV prefetch.
57	    /// Offered at most once; a no-hit offer leaves the request in the normal
58	    /// admission flow with this set so it isn't re-probed every tick.
59	    pub(crate) prefetch_offered: bool,
60	    /// Prompt tokens whose KV is already computed (prefix-cache hits plus
61	    /// chunks applied in earlier steps). Updated from the executor's
62	    /// authoritative position after every chunk.
63	    pub(crate) prefill_pos: usize,
64	    /// Prompt tokens to forward in the upcoming step. Set by
65	    /// `take_prefill_chunks` when the request is packed into a step.
66	    pub(crate) step_chunk: usize,
67	}
68	
69	impl PendingRequest {
70	    pub(crate) fn from_request(request_id: RequestId, req: Request) -> Self {
71	        Self {
72	            request_id,
73	            lora_adapter: req.lora_adapter,
74	            prompt_tokens: req.prompt_tokens,
75	            params: req.params,
76	            stop_policy: req.stop_policy,
77	            max_tokens: req.max_tokens,
78	            logprobs: req.logprobs,
79	            prompt_logprobs: req.prompt_logprobs,
80	            prefetch_offered: false,
81	            prefill_pos: 0,
82	            step_chunk: 0,
83	        }
84	    }
85	
86	    fn remaining_prompt_tokens(&self) -> usize {
87	        self.prompt_tokens.len() - self.prefill_pos
88	    }
89	}
90	
91	/// Pull the next prefill step set off the front of `prefilling`, capping the
92	/// step's total forwarded tokens at `max_prefill_tokens`. Each taken request
93	/// gets its per-step chunk recorded in `step_chunk`. Prompt-logprob requests need
94	/// logits for every prompt position in one forward, so they only run when
95	/// their whole remainder fits the profiled prefill bound. Under request-local
96	/// chunking, a request takes `min(remaining, max_prefill_tokens)` whole or skips
97	/// the step, so its chunk boundaries depend only on its own length and are
98	/// batch-invariant.
99	pub(crate) fn take_prefill_chunks(
100	    prefilling: &mut Vec<PendingRequest>,
101	    max_prefill_tokens: usize,
102	    request_local: bool,
103	) -> Vec<PendingRequest> {
104	    let mut budget = max_prefill_tokens;
105	    let mut taken: Vec<PendingRequest> = Vec::new();
106	    let mut i = 0;
107	    while i < prefilling.len() && budget > 0 {
108	        let remaining = prefilling[i].remaining_prompt_tokens();
109	        let chunk = if prefilling[i].prompt_logprobs.is_some() {
110	            if remaining > budget {
111	                i += 1;
112	                continue;
113	            }
114	            remaining
115	        } else if request_local {
116	            let desired = remaining.min(max_prefill_tokens);
117	            if desired > budget {
118	                i += 1;
119	                continue;
120	            }
121	            desired
122	        } else {
123	            remaining.min(budget)
124	        };
125	        let mut req = prefilling.remove(i);
126	        req.step_chunk = chunk;
127	        budget = budget.saturating_sub(chunk);
128	        taken.push(req);
129	    }
130	    // Whole-or-skip may select later requests; sort to match request-id-ordered results.
131	    taken.sort_by_key(|req| req.request_id);
132	    taken
133	}
134	
135	pub(crate) fn servable_len(max_context: usize, max_blocks: usize, block_size: usize) -> u32 {
136	    max_context
137	        .min(max_blocks.saturating_mul(block_size))
138	        .try_into()
139	        .unwrap_or(u32::MAX)
140	}
