142	// ── KV-offload prefetch admission helpers ────────────────────────────────
143	
144	/// Move requests whose async CPU-tier prefetch just settled from `loading`
145	/// back to the front of `deferred` — their KV is hot, so admit them first.
146	pub(crate) fn reclaim_ready_prefetch<E: ModelExecutor>(
147	    executor: &mut E,
148	    deferred: &mut Vec<PendingRequest>,
149	    loading: &mut Vec<PendingRequest>,
150	    // Free blocks already promised to admitted requests; a remote fetch that
151	    // resolves during this sweep must not reserve into them.
152	    reserve_floor: usize,
153	) {
154	    promote_ready(
155	        executor.drain_ready_prefetch(reserve_floor),
156	        deferred,
157	        loading,
158	    );
159	}
160	
161	/// Offer each not-yet-offered `deferred` request to async CPU-tier prefetch,
162	/// moving the ones that start loading out of `deferred` into `loading`. A
163	/// request that doesn't start a load (pure GPU hit, miss, or block pressure)
164	/// stays in `deferred`, flagged so it isn't re-probed next tick.
165	///
166	/// Prompt-logprob requests are never offered: their prefill forwards the whole prompt to
167	/// recover prompt logprobs and so skips `match_and_add_prefix` (see
168	/// `execute_prefill`). Prefetched blocks would never be matched/reused — they
169	/// would only park restored KV that admission credits but prefill can't spend,
170	/// starving the request under tight budgets. Leaving `prefetch_offered` unset
171	/// for prompt-logprob requests is harmless: the `req.prompt_logprobs.is_none()` guard keeps them from being probed.
172	pub(crate) fn offer_prefetch<E: ModelExecutor>(
173	    executor: &mut E,
174	    deferred: &mut Vec<PendingRequest>,
175	    loading: &mut Vec<PendingRequest>,
176	    // Free blocks already promised to admitted requests; the prefetch must
177	    // leave them untouched (see `ModelExecutor::begin_kv_prefetch`).
178	    reserve_floor: usize,
179	) {
180	    let mut keep = Vec::with_capacity(deferred.len());
181	    for mut req in deferred.drain(..) {
182	        if !req.prefetch_offered && req.prompt_logprobs.is_none() {
183	            req.prefetch_offered = true;
184	            if executor.begin_kv_prefetch(
185	                req.request_id,
186	                &req.prompt_tokens,
187	                req.lora_adapter.as_deref(),
188	                reserve_floor,
189	            ) {
190	                loading.push(req);
191	                continue;
192	            }
193	        }
194	        keep.push(req);
195	    }
196	    *deferred = keep;
197	}
