125	    // Speculative decoding loads its draft model after the target is up (the
126	    // draft is built against the target's embeddings/head) and forces the
127	    // prefix cache off, so it must follow set_no_prefix_cache. Its GPU footprint
128	    // was already reserved during profiling from the draft path passed above.
129	    if let Some(draft_path) = dflash_draft_model_path {
130	        executor.load_dflash_draft_model(draft_path)?;
131	    }
132	
133	    Ok(start_with_executor(
134	        executor,
135	        seed,
136	        max_prefill_tokens,
137	        false,
138	    ))
139	}
