171	/// Wrap a ready executor in the scheduler and hand the whole thing to the
172	/// contract: one scheduler, one driver thread, required metadata filled in.
173	pub(crate) fn start_with_executor<E>(
174	    executor: E,
175	    seed: u64,
176	    max_prefill_tokens: usize,
177	    lora_control: bool,
178	) -> Engine
179	where
180	    E: ModelExecutor + 'static,
181	{
182	    assert!(
183	        max_prefill_tokens > 0,
184	        "max_prefill_tokens must be positive: a zero budget can never schedule a prefill chunk"
185	    );
186	    let servable = servable_len(
187	        executor.max_context_tokens(),
188	        executor.max_request_blocks(),
189	        executor.block_size(),
190	    );
191	    // Executor just built: the only committed block is the leaked CUDA-graph
192	    // padding slot, so available_blocks() is total − 1. Conservative by one
193	    // block, which is the right side to err on for a capacity ceiling.
194	    let kv_total = executor.available_blocks() as u64;
195	    let kv_capacity = KvCapacity {
196	        total_blocks: kv_total as usize,
197	        block_size: executor.block_size(),
198	    };
199	    // The LoRA channel is qwen3's private wiring, minted before the thread
200	    // swallows the scheduler; the contract only carries the client.

